mod solution;

fn main() {
    let cases = [
    (r#"[1,2,3,4,5,null,6]"#, r#"1,2,4,5,3,6"#),
    (r#"[1,2,3]"#, r#"1,2,3"#),
    (r#"
[1,2,3]
"#, r#"1,2,3"#),
    (r#"  
[1,2,3,4,5,null,6]
  "#, r#"1,2,4,5,3,6"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS tree-preorder");
}
